    auto roundtrip=[&](const Document& d,const std::string& name){auto expected=studio::analyze(d,[&](){std::vector<ObjectRef> refs;for(const auto& a:d.atoms().records())if(a.isAlive())refs.emplace_back(ObjectKind::Atom,a.id);return refs;}());std::string xml,binary,decoded,why;require(studioio::exportXml(d,&xml).ok(),"CDXML export");std::ofstream(dir+"/"+name+".cdxml")<<xml;
        require(cdxbinary::fromXml(xml,binary,why)&&cdxbinary::toXml(binary,decoded,why),"CDX metadata: "+why);std::ofstream(dir+"/"+name+".cdx",std::ios::binary).write(binary.data(),binary.size());
        tinyxml2::XMLDocument nativeTree;nativeTree.Parse(xml.c_str());std::function<void(tinyxml2::XMLElement*)> nativeSave=[&](tinyxml2::XMLElement* e){std::vector<std::string> keys;for(auto a=e->FirstAttribute();a;a=a->Next())if(std::string(a->Name()).compare(0,24,"MoleculeStudioProjection")==0)keys.push_back(a->Name());for(auto key:keys)e->DeleteAttribute(key.c_str());for(auto c=e->FirstChildElement();c;c=c->NextSiblingElement())nativeSave(c);};nativeSave(nativeTree.RootElement());tinyxml2::XMLPrinter nativePrinter;nativeTree.Print(&nativePrinter);std::string native=nativePrinter.CStr();
        for(const auto& bytes:{xml,decoded,native}){Session back;require(persistence::readCdxml(bytes,back.doc).ok(),"reopen molecular projection");back.refresh();auto actual=studio::analyze(back.doc,back.all());require(actual.valid==expected.valid&&actual.plain==expected.plain&&std::abs(actual.averageMass-expected.averageMass)<1e-6,"formula/mass after reopening");int oldC=0,newC=0,oldV=0,newV=0;for(const auto& a:d.atoms().records())if(a.isAlive())oldC+=projection_molecule::marked(d,a.id);for(const auto& a:back.doc.atoms().records())if(a.isAlive())newC+=projection_molecule::marked(back.doc,a.id);for(const auto& b:d.bonds().records())if(b.isAlive())for(auto c:{b.beginAtom,b.endAtom})oldV+=d.extensions(ObjectRef(ObjectKind::Bond,b.id)).findValue(projection_molecule::vectorKey(b,c))!=nullptr;for(const auto& b:back.doc.bonds().records())if(b.isAlive())for(auto c:{b.beginAtom,b.endAtom})newV+=back.doc.extensions(ObjectRef(ObjectKind::Bond,b.id)).findValue(projection_molecule::vectorKey(b,c))!=nullptr;require(oldC==newC&&oldV==newV,"projection view and stereo metadata survive CDXML/CDX");}
    };
    if(const char* path=std::getenv("MOLECULE_STUDIO_PROJECTION_NATIVE_SOURCE")){Session native;require(native.open(path).ok(),"actual ChemDraw projection reopen");int cores=0,paths=0,arrows=0;for(const auto& a:native.doc.atoms().records())if(a.isAlive())cores+=projection_molecule::kind(native.doc,a.id)==2;for(const auto& p:native.doc.paths().records())paths+=p.isAlive();for(const auto& a:native.doc.arrows().records())arrows+=a.isAlive();auto formula=studio::analyze(native.doc,native.all());require(cores==2&&paths==0&&arrows==0&&formula.valid&&formula.plain=="C8H18O","ChemDraw object tags restore projection without duplicate ink");roundtrip(native.doc,"after-chemdraw");}
    int variants=0,conversions=0;
    for(int kind=0;kind<3;++kind)for(int variant=kind==0?1:0;variant<(kind==0?13:2);++variant){auto source=stereo_projection::make(style,kind,variant);auto stats=source->doc.stats();require(stats.aliveAtoms==(kind==0?3*variant+2:8)&&stats.aliveBonds==stats.aliveAtoms-1&&stats.aliveTexts==0,"real atomic graph without caption substitutes");auto formula=studio::analyze(source->doc,source->all());int carbons=kind==0?3*variant+2:8;require(formula.valid&&formula.plain=="C"+std::to_string(carbons)+"H"+std::to_string(2*carbons+2),"native selection formula: "+formula.plain);roundtrip(source->doc,"template-"+std::to_string(variants++));}
    // Files made by the former vector-only implementation acquire atom graphs.
    {stereo_projection::Builder old(style);old.group->SetAttribute("Name","Fischer projection");old.line(Vec2(0,-20),Vec2(0,20));old.line(Vec2(),Vec2(-20,0));old.line(Vec2(),Vec2(20,0));auto upgraded=stereo_projection::finish(old);require(upgraded->doc.stats().aliveAtoms==5&&upgraded->doc.stats().aliveBonds==4,"old vector Fischer upgrades on open");roundtrip(upgraded->doc,"legacy-fischer");}
    for(int kind=1;kind<=2;++kind){stereo_projection::Builder old(style);old.group->SetAttribute("Name",kind==1?"Sawhorse projection":"Newman projection");Vec2 c[2]={kind==1?Vec2(-28,13):Vec2(),kind==1?Vec2(28,-13):Vec2()};if(kind==1)old.line(c[0],c[1]);else{old.circle(Vec2(),8.8,false);old.circle(Vec2(),.6,true);}for(int plane=0;plane<2;++plane)for(int i=0;i<3;++i){double angle=(kind==1?i*120.+(plane?60.:0.):-90.+i*120.+(plane?60.:0.))*3.141592653589793/180;Vec2 ray(cos(angle),sin(angle));if(kind==1){ray.x+=.35*ray.y;ray=ray*(1/length(ray));}auto tip=c[plane]+ray*(kind==1?(plane?16.4:18.):22.4);old.line(c[plane]+ray*(kind==2&&plane?8.8:0),tip);}auto upgraded=stereo_projection::finish(old);require(upgraded->doc.stats().aliveAtoms==8&&upgraded->doc.stats().aliveBonds==7,"legacy paired projection upgrades on open");roundtrip(upgraded->doc,"legacy-"+std::to_string(kind));}
    Session gallery;gallery.doc=style;studioio::Page page;page.width=490;page.height=340;page.x=page.y=0;page.store(gallery.doc);
    const int kinds[]={0,1,2,1,2},values[]={2,0,0,1,1};
    for(int i=0;i<5;++i){reset(style);auto before=app.s.doc.digest();app.armProjection(kinds[i],values[i]);require(app.bioPlacing&&app.s.doc.digest()==before,"placement preview is nonmutating");app.cancelBioPlacement();require(app.s.doc.digest()==before,"cancel placement");app.armProjection(kinds[i],values[i]);app.placeBioComponent(Vec2(90,90));require(app.s.doc.stats().aliveAtoms==8,"insertion copies molecular graph");require(studio::analyze(app.s.doc,app.s.selected).valid,"selected insertion shows molecular weight");require(app.s.undo().ok()&&app.s.doc.digest()==before&&app.s.undo(true).ok(),"placement undo redo");
        app.s.fit();ObjectId tipId=kInvalidObjectId;for(const auto& a:app.s.doc.atoms().records())if(a.isAlive()&&app.s.doc.incidentBonds(a.id).size()==1){tipId=a.id;break;}auto tip=app.s.doc.atoms().alive(tipId)->position;
        auto click=[&](bool twice){auto pixel=app.s.view().toDevice(tip);auto pos=MAKELPARAM(int(std::lround(pixel.x)),int(std::lround(pixel.y)));SendMessageW(app.canvas,WM_MOUSEMOVE,0,pos);SendMessageW(app.canvas,WM_LBUTTONDOWN,MK_LBUTTON,pos);SendMessageW(app.canvas,WM_LBUTTONUP,0,pos);if(twice){SendMessageW(app.canvas,WM_LBUTTONDBLCLK,MK_LBUTTON,pos);SendMessageW(app.canvas,WM_LBUTTONUP,0,pos);}};
        auto view=app.s.view();for(double zoom:{1.,2.,4.}){auto v=view;v.scale=zoom;app.s.setView(v);auto pixel=app.s.view().toDevice(tip)+Vec2(5,0);SendMessageW(app.canvas,WM_MOUSEMOVE,0,MAKELPARAM(int(pixel.x),int(pixel.y)));Vec2 captured;require(app.projectionCapture(app.pointerPixel,&captured)&&length(captured-tip)<.01,"device-sized endpoint capture");}app.s.setView(view);
        // Exercise the actual Windows key/character pair: the follow-up WM_CHAR
        // must not undo an element shortcut by opening the old caption editor.
        app.s.activateCommand("chooseSelectionTool_Marquee");
        auto elementKey=[&](UINT key,WPARAM character,int element,const std::string& formula){
            // Aim at this endpoint itself: in eclipsed Newman views its partner
            // may be only a few pixels away at low zoom.
            auto pixel=app.s.view().toDevice(tip);SendMessageW(app.canvas,WM_MOUSEMOVE,0,MAKELPARAM(int(std::lround(pixel.x)),int(std::lround(pixel.y))));
            auto beforeKey=app.s.doc.digest();auto cursor=app.s.history.cursor();auto selected=app.s.selected;
            SendMessageW(app.canvas,WM_KEYDOWN,key,1);SendMessageW(app.canvas,WM_CHAR,character,1);SendMessageW(app.canvas,WM_KEYUP,key,1);
            require(!app.textEditor.active&&app.s.doc.atoms().alive(tipId)->element==element,"hover shortcut "+std::string(1,char(key))+" view "+std::to_string(i)+" zoom "+std::to_string(app.s.view().scale)+" handles key and character");
            auto result=studio::analyze(app.s.doc,app.s.all());require(result.valid&&result.plain==formula,"hover shortcut "+std::string(1,char(key))+" updates formula: "+result.plain+" / "+result.note);
            require(app.s.doc.stats().aliveAtoms==8&&app.s.doc.stats().aliveTexts==0&&app.s.selected==selected,"shortcut changes only hovered atom, without captions");
            auto afterKey=app.s.doc.digest();auto context="element shortcut "+std::string(1,char(key))+" view "+std::to_string(i);
            require(app.s.history.cursor()==cursor+1,context+" adds exactly one history entry");
            require(app.s.undo().ok()&&app.s.doc.digest()==beforeKey,context+" undo restores full document");
            require(app.s.undo(true).ok()&&app.s.doc.digest()==afterKey,context+" redo restores full document");
        };
        for(double zoom:{1.,2.,4.}){auto v=view;v.scale=zoom;app.s.setView(v);elementKey('B','b',35,"C7H15Br");elementKey('L','l',17,"C7H15Cl");elementKey('C','c',6,"C8H18");}app.s.setView(view);
        elementKey('N','n',7,"C7H17N");elementKey('O','o',8,"C7H16O");elementKey('C','c',6,"C8H18");
        app.s.activateCommand("chooseEdittingTool_Text");click(false);require(app.textEditor.active&&app.textEditor.atom==tipId,"text tool edits a real atom");SetWindowTextW(app.textEditor.hwnd,L"Cl");require(app.finishText(true)&&app.s.doc.atoms().alive(tipId)->element==17,"element edit changes chemistry");auto chlorine=studio::analyze(app.s.doc,app.s.all());require(chlorine.valid&&chlorine.plain=="C7H15Cl","substituent changes formula: "+chlorine.plain);
        app.s.activateCommand("chooseSelectionTool_Marquee");click(true);require(app.textEditor.active&&app.textEditor.atom==tipId,"double click reopens atom");SetWindowTextW(app.textEditor.hwnd,L"CH2OH");require(app.finishText(true),"edit expandable group");auto longGroup=studio::analyze(app.s.doc,app.s.all());require(longGroup.valid&&longGroup.plain=="C8H18O","group contributes real formula: "+longGroup.plain+" / "+longGroup.note);require(app.s.undo().ok()&&app.s.doc.atoms().alive(tipId)->element==17&&app.s.undo(true).ok(),"group undo redo");
        elementKey('B','b',35,"C7H15Br");require(app.s.undo().ok()&&studio::analyze(app.s.doc,app.s.all()).plain==longGroup.plain,"undo restores replaced group");
        elementKey('L','l',17,"C7H15Cl");require(app.s.undo().ok()&&studio::analyze(app.s.doc,app.s.all()).plain==longGroup.plain,"chlorine replacement restores group on undo");
        app.s.selected=app.s.all();auto axis=app.projectionAxis(app.s.doc.atoms().alive(tipId)->position);require(axis!=kInvalidObjectId,"context menu finds projection axis");auto graph=signature(app.s.doc);auto base=app.s.doc;
        for(int target=0;target<5;++target){reset(base);app.s.selected=app.s.all();auto original=app.s.doc.digest();app.convertProjection(axis,kinds[target],values[target]);require(app.s.doc.digest()!=original||target==i,"conversion applies view");require(signature(app.s.doc)==graph,"conversion preserves atom IDs and bond graph");auto f=studio::analyze(app.s.doc,app.s.selected);require(f.valid&&f.plain==longGroup.plain&&std::abs(f.averageMass-longGroup.averageMass)<1e-6,"conversion preserves selected formula/mass");auto converted=app.s.doc.digest();if(converted!=original)require(app.s.undo().ok()&&app.s.doc.digest()==original&&app.s.undo(true).ok()&&app.s.doc.digest()==converted,"conversion one-step undo redo");roundtrip(app.s.doc,"converted-"+std::to_string(i)+"-"+std::to_string(target));++conversions;}
        auto source=stereo_projection::make(style,kinds[i],values[i]);auto bounds=source->scene.bounds();require(studioio::append(source->doc,gallery.doc,source->all(),Vec2(85+(i%3)*160,85+(i/3)*155)-(bounds.min+bounds.max)*.5,nullptr).ok(),"copy projection graph");
    }
    {auto source=stereo_projection::make(style,1,0);auto axis=axisOf(source->doc);std::vector<ObjectId> leaves;for(const auto& a:source->doc.atoms().records())if(a.isAlive()&&source->doc.incidentBonds(a.id).size()==1)leaves.push_back(a.id);ObjectId oxygen,bond;require(source->doc.addAtom(source->doc.atoms().alive(leaves[0])->position+Vec2(0,20),8,&oxygen).ok()&&source->doc.addBond(leaves[0],oxygen,&bond).ok(),"ordinary atom/bond extension");auto f=studio::analyze(source->doc,source->all());require(f.valid&&f.plain=="C8H18O","extended structure formula");auto graph=signature(source->doc);require(projection_molecule::convert(source->doc,axis,2,0).ok()&&signature(source->doc)==graph,"conversion retains extended branch");require(source->doc.removeAtom(oxygen).ok()&&studio::analyze(source->doc,source->all()).plain=="C8H18","ordinary atom deletion");source->doc.addBond(leaves[0],leaves[3],&bond);auto before=source->doc.digest();require(!projection_molecule::convert(source->doc,axis,0,0).ok()&&source->doc.digest()==before,"ring conversion refuses atomically");}
    // A one-centre Fischer may be viewed down its terminal carbon-carbon bond.
    {auto source=stereo_projection::make(style,0,1);auto formula=studio::analyze(source->doc,source->all());auto edge=source->doc.bonds().records().front().id;require(projection_molecule::convert(source->doc,edge,2,0).ok(),"single-centre Fischer conversion");auto after=studio::analyze(source->doc,source->all());require(after.plain==formula.plain,"explicit-H conversion preserves formula");}
    Session sugarGallery;sugarGallery.doc=style;
    for(int mirror=0;mirror<2;++mirror)for(size_t i=0;i<stereo_projection::sugars().size();++i){auto source=stereo_projection::sugar(style,int(i),mirror);const auto& entry=stereo_projection::sugars()[i];int n=int(std::string(entry.hydroxyl).size())+(entry.ketose?3:2);auto formula=studio::analyze(source->doc,source->all());require(formula.valid&&formula.plain=="C"+std::to_string(n)+"H"+std::to_string(n*2)+"O"+std::to_string(n),"sugar real molecular formula: "+std::string(entry.title)+" "+formula.plain);roundtrip(source->doc,"sugar-"+std::to_string(i)+(mirror?"-L":"-D"));
        if(i==9&&!mirror){reset(source->doc);app.s.selected=app.s.all();std::string answer;require(app.prepareStereoLabels(&answer)&&answer.find("\natom\t")!=std::string::npos,"sugar atom CIP annotation: "+answer);std::ofstream(dir+"/glucose-stereo.tsv")<<answer;auto axis=axisOf(app.s.doc);for(int j=0;j<5;++j){require(projection_molecule::convert(app.s.doc,axis,kinds[j],values[j]).ok(),"sugar projection conversion");roundtrip(app.s.doc,"glucose-converted-"+std::to_string(j));}}
    }
