    std::ofstream(dir+"/projection-checks.json")<<"{\"molecular_variants\":"<<variants<<",\"conversion_pairs\":"<<conversions<<",\"native_atom_editing\":true,\"hover_element_shortcuts\":70,\"shortcut_character_consumed\":true,\"group_replacement_undo\":true,\"formula_mass\":true,\"capture\":true,\"undo_redo\":true,\"cdxml_cdx_metadata\":true,\"sugar_formulas\":36,\"atom_stereo_labels\":true}";
